"""Post-call structured summary generated by LLM."""

import uuid
from typing import TYPE_CHECKING, Any, Dict, List, Optional
from sqlalchemy import Boolean, ForeignKey, JSON, String, Text
from sqlalchemy.orm import Mapped, mapped_column, relationship
from backend.app.models.base import GUID, Base, TimestampMixin

if TYPE_CHECKING:
    from backend.app.models.call import Call


class CallSummary(Base, TimestampMixin):
    """Analytical summary and extracted insights for a completed call."""

    __tablename__ = "call_summaries"

    id: Mapped[uuid.UUID] = mapped_column(
        GUID(), primary_key=True, default=uuid.uuid4
    )
    call_id: Mapped[uuid.UUID] = mapped_column(
        GUID(), ForeignKey("calls.id", ondelete="CASCADE"), unique=True, nullable=False
    )
    primary_intent: Mapped[str] = mapped_column(String(100), nullable=False)
    executive_summary: Mapped[str] = mapped_column(Text, nullable=False)
    key_points_discussed: Mapped[List[Any]] = mapped_column(JSON, default=list, nullable=False)
    customer_objections: Mapped[List[Any]] = mapped_column(JSON, default=list, nullable=False)
    action_items: Mapped[List[Any]] = mapped_column(JSON, default=list, nullable=False)
    lead_qualification_summary: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    follow_up_recommended: Mapped[bool] = mapped_column(Boolean, default=False, nullable=False)

    # Relationships
    call: Mapped["Call"] = relationship("Call", back_populates="call_summary")
